/* @autogenerated */
package net.civeira.phylax.features.notification.outbox.application.usecase.enqueue;

import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.Map;
import java.util.NoSuchElementException;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.features.access.tenant.domain.TenantRef;
import net.civeira.phylax.features.document.rendering.application.usecase.render.TemplateRenderInput;
import net.civeira.phylax.features.document.rendering.application.usecase.render.TemplateRenderUsecase;
import net.civeira.phylax.features.document.rendering.domain.RenderedTemplate;
import net.civeira.phylax.features.document.rendering.domain.TemplateOutputFormat;
import net.civeira.phylax.features.document.template.domain.TemplateChannelOptions;
import net.civeira.phylax.features.notification.message.domain.Message;
import net.civeira.phylax.features.notification.message.domain.MessageChangeSet;
import net.civeira.phylax.features.notification.message.domain.gateway.MessageWriteRepositoryGateway;
import net.civeira.phylax.features.notification.message.infrastructure.event.MessageEventDispatcher;
import net.civeira.phylax.features.notification.outbox.domain.ChannelOptions;
import net.civeira.phylax.features.notification.outbox.domain.event.UrgentMessageEnqueuedEvent;

/**
 * Creates a {@link Message} in the outbox by rendering the requested template and persisting the
 * result as a pending notification.
 *
 * <p>
 * The rendered content (subject + HTML + optional plain text) is serialised to JSON and stored in
 * {@link Message#getContent()} so the dispatch service can reconstruct the email without additional
 * rendering.
 * </p>
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class EnqueueNotificationUseCase {

  private final TemplateRenderUsecase renderUsecase;
  private final MessageWriteRepositoryGateway messageGateway;
  private final MessageEventDispatcher eventDispatcher;
  private final ObjectMapper objectMapper;
  private final Event<UrgentMessageEnqueuedEvent> urgentEvents;

  /**
   * Renders the template and persists the resulting message in the outbox queue.
   *
   * @param cmd the enqueue command
   * @return the persisted {@link Message}
   */
  @Transactional
  public Message enqueue(EnqueueNotificationCommand cmd) {
    TenantRef tenantRef = cmd.getTenantOptional().orElse(null);

    TemplateRenderInput renderInput =
        TemplateRenderInput.builder().code(cmd.getTemplateCode()).channel(channel(cmd.getChannel()))
            .tenant(tenantRef).variables(flattenVariables("", cmd.getVariables()))
            .outputFormat(TemplateOutputFormat.HTML_EMBEDDED).build();

    RenderedTemplate rendered = renderUsecase.render(renderInput)
        .orElseThrow(() -> new NoSuchElementException("No enabled template found for code="
            + cmd.getTemplateCode() + " channel=" + cmd.getChannel()));

    String content = encodeContent(rendered);

    MessageChangeSet changeSet = new MessageChangeSet().newUid().target(cmd.getRecipient())
        .content(content).retries(0).urgent(cmd.isUrgent())
        .createdAt(OffsetDateTime.now(ZoneOffset.UTC)).sendAt(cmd.getSendAt());

    cmd.getTenantOptional().ifPresent(changeSet::tenant);

    Message message = Message.create(changeSet);
    Message saved = messageGateway.create(message);
    eventDispatcher.dispatch(saved);

    if (cmd.isUrgent()) {
      urgentEvents.fire(new UrgentMessageEnqueuedEvent(saved.getUid()));
    }

    return saved;
  }

  /**
   * Serialises the rendered template output to a JSON string for storage in the outbox.
   *
   * <p>
   * The JSON format is {@code {"subject":"…","html":"…","text":"…"}}. When serialisation fails the
   * raw HTML is returned as a fallback so the message is never silently lost.
   * </p>
   *
   * @param rendered the fully rendered template
   * @return a JSON-encoded content string, or raw HTML on serialisation failure
   */
  private String encodeContent(RenderedTemplate rendered) {
    try {
      return objectMapper.writeValueAsString(new RenderedContent(rendered.getSubject().orElse(""),
          rendered.getHtmlContent(), rendered.getTextContent().orElse(null)));
    } catch (JsonProcessingException e) {
      log.warn("Failed to serialise rendered template content as JSON, using html only", e);
      return rendered.getHtmlContent();
    }
  }

  /**
   * Recursively flattens a nested variable map to dotted-key notation.
   *
   * <p>
   * For example, {@code {user: {name: "John"}}} becomes {@code {"user.name": "John"}}. Null values
   * are skipped; non-Map values are converted with {@link Object#toString()}.
   * </p>
   *
   * @param prefix the key prefix accumulated from parent levels (empty string at root)
   * @param map the (possibly nested) variables map to flatten
   * @return a flat {@code Map<String, String>} suitable for {@link TemplateRenderInput}
   */
  @SuppressWarnings("unchecked")
  private Map<String, String> flattenVariables(String prefix, Map<String, Object> map) {
    Map<String, String> result = new HashMap<>();
    for (Map.Entry<String, Object> entry : map.entrySet()) {
      String key = prefix.isEmpty() ? entry.getKey() : prefix + "." + entry.getKey();
      if (entry.getValue() instanceof Map<?, ?> nested) {
        result.putAll(flattenVariables(key, (Map<String, Object>) nested));
      } else if (entry.getValue() != null) {
        result.put(key, entry.getValue().toString());
      }
    }
    return result;
  }

  /**
   * Internal JSON serialisation shape for storing the rendered email in the outbox.
   *
   * @param subject email subject line
   * @param html HTML body
   * @param text plain-text alternative; null when absent
   */
  record RenderedContent(String subject, String html, String text) {}

  private TemplateChannelOptions channel(ChannelOptions opts) {
    return TemplateChannelOptions.valueOf(opts.name());
  }
}
